import{d as c,C as t,o as m,c as u,j as a,a as o,E as n,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第六章","description":"从谷神与玄牝的譬喻，读到天地根、绵绵若存与用而不劳。","frontmatter":{"title":"道德经第六章","description":"从谷神与玄牝的譬喻，读到天地根、绵绵若存与用而不劳。","category":"guide","aliases":["道德经第六章","老子第六章","dao de jing chapter 6"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-06.md","filePath":"daoism/dao-de-jing/chapter-06.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-06.md"},P=c({...b,setup(x){const i=[{id:"valley-and-mysterious-female",label:"谷神不死，是谓玄牝",showLabel:!0,sentences:[[{text:"谷神",glossary:"gushen"},"不死，是谓",{text:"玄牝",glossary:"xuanpin"},"。"]],note:["【白话】像空谷一般虚而灵妙的作用，长存而不衰，这称为幽深的生养之源。","【王弼注择要】「无形无影，无逆无违，处卑不动，守静不衰。」王弼从无形、处卑、守静说明谷的作用，而非为山谷另立一位有形神祇。","【读法】谷取虚而能容之象，牝取雌性、生养之象。二者帮助描述根源，不能直接还原成一种具体器官，也不由此规定现实男女的社会角色。"]},{id:"gateway-and-root",label:"玄牝之门，是谓天地根",showLabel:!0,sentences:[["玄牝之",{text:"门",glossary:"men"},"，是谓天地根。"]],note:["【白话】这一幽深生养之源所由出的门径，称为天地的根本。","【王弼注择要】「门，玄牝之所由也。」注以门说明所由，以根说明根本；它们不是要给天地找一扇可以测量位置的门。","【读法】从谷到牝，再到门与根，譬喻不断变化，所追问的仍是万物怎样有所由。可与第一章的「众妙之门」相互参读，不必把两处门硬定为同一件实物。"]},{id:"continuous-and-unlaboured",label:"绵绵若存，用之不勤",showLabel:!0,sentences:[[{text:"绵绵",glossary:"mianmian"},"若存，用之不",{text:"勤",glossary:"qin"},"。"]],note:["【白话】绵延不绝，仿佛有所存在；发挥作用，却不劳倦。","【王弼注择要】「欲言存邪，则不见其形；欲言亡邪，万物以之生。」又说「无物不成，用而不劳也」。前一句解释若存的迟疑，后一句说明不勤的作用。","【读法】本页依王弼把勤解释为劳，不沿用旧页「勤通尽」的说法。若存也不只是似有似无的感受，而是在不见其形与万物由以生之间作说明。"]}],r=[{id:"gushen",term:"谷神",sense:1},{id:"xuanpin",term:"玄牝",sense:1},{id:"men",term:"门",sense:1,context:"玄牝所由的门径，借喻生成有所从来。"},{id:"mianmian",term:"绵绵",sense:1},{id:"qin",term:"勤",sense:1}];return(g,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六章",tabindex:"-1"},[o("道德经第六章 "),a("a",{class:"header-anchor",href:"#道德经第六章","aria-label":'Permalink to "道德经第六章"'},"​")],-1)),n(s,{title:"从虚谷读到生养的根源",summary:"第五章借橐龠说虚中能用，本章用谷、牝、门与根继续追问生养所由。先跟随譬喻进入，再留意「若存」为何不把根源说成一件有形的东西。",points:[{label:"先读",text:"谷与牝分别带出什么形象？"},{label:"再辨",text:"门与根怎样把譬喻指向所由？"},{label:"后想",text:"不见其形，为什么又不能说它全无？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),n(l,{sections:i,glossary:r,tone:"ink",density:"comfortable","aria-label":"《道德经》第六章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"谷神不死，是谓玄牝。",tone:"取象",guide:"谷的虚与牝的生养连在一起，打开对根源的想象。王弼着重说明无形、处卑、守静，不把譬喻固定成一个具体神灵。"},{text:"玄牝之门，是谓天地根。",tone:"溯源",guide:"门说明所由，根说明根本。文字在几种形象之间移动，帮助人追问生成，而非描绘一件可定位的物体。"},{text:"绵绵若存，用之不勤。",tone:"体用",guide:"若存承认难以指认其形，不勤则说明作用而不劳。两者并读，才不至于只留下玄远的气氛。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-本章为什么换用这么多譬喻" tabindex="-1">象：本章为什么换用这么多譬喻？ <a class="header-anchor" href="#象-本章为什么换用这么多譬喻" aria-label="Permalink to &quot;象：本章为什么换用这么多譬喻？&quot;">​</a></h3><p>空谷让人想到容受与处下，牝让人想到生养，门与根又分别指出所由与根本。每个譬喻只打开一个侧面；若抓住某一个形象，便宣布已经知道道是什么，反而会丢掉文字继续转换的用意。</p><h3 id="理-「若存」是在怀疑道的存在吗" tabindex="-1">理：「若存」是在怀疑道的存在吗？ <a class="header-anchor" href="#理-「若存」是在怀疑道的存在吗" aria-label="Permalink to &quot;理：「若存」是在怀疑道的存在吗？&quot;">​</a></h3><p>王弼给出两边的理由：要说它存在，却不见其形；要说它不存在，万物又由以生成。因此用若存保留言说的分寸。这里的存亡问题属于对万物根源的思考，不能直接换成现代实验已经证实某种隐藏能量的说法。</p><h3 id="用-怎样从「用而不劳」得到实际启发" tabindex="-1">用：怎样从「用而不劳」得到实际启发？ <a class="header-anchor" href="#用-怎样从「用而不劳」得到实际启发" aria-label="Permalink to &quot;用：怎样从「用而不劳」得到实际启发？&quot;">​</a></h3><p>可以先问：一件事的持续，是否全靠不断加力，还是有更合宜的条件与节律？例如学习需要适度练习，也需要消化与休息。这是由古注引出的提问，不意味着人能不费力地完成所有事情，更不是不劳而获的承诺。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>帮助生长，先检查容受的空间。</strong> 教学与协作中，除了增加指导，还可检查有没有让人尝试、提问和自行调整的余地。空间与支持相配，才能使留白成为生成条件。</p><p><strong>不要把譬喻急着变成事实。</strong> 读到母体、根源或门户时，先说明它们帮助理解什么，再辨认比喻的限度。保留形象的启发力，也给后续核实留下位置。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否把某个熟悉的譬喻当成了事物本身？眼下要持续的一件事，需要再加力，还是先整理条件与节律？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>「勤」依王弼「用而不劳也」取劳倦义，不采用旧页「勤通尽」的解释。</li><li>「谷神」「玄牝」按虚静与生养的譬喻理解；若另从宗教或养生传统解读，应区分其解释层次。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，004b–005a</a>。</p>',15))])}}});export{_ as __pageData,P as default};
